import React,{useMemo,useState} from 'react';
import {Alert,Image,Modal,Pressable,ScrollView,StyleSheet,Text,View,useWindowDimensions} from 'react-native';
import {SafeAreaProvider,SafeAreaView} from 'react-native-safe-area-context';
import {StatusBar} from 'expo-status-bar';
import * as ImagePicker from 'expo-image-picker';
import DateTimePicker from '@expo/ui/community/datetime-picker';
import {agents as seedAgents,areas as seedAreas,customers as seedCustomers,loans,collections as seedCollections,expenses as seedExpenses,chits,leaves as seedLeaves} from './data/demoData';
import {Collection,Customer,Expense,Role,Branding,Agent,Area,Leave} from './types';
import {C,Card,Button,Input,SectionTitle,Status,Pill} from './components/ui';
import {money} from './utils/format';
import {exportExcel,exportPdf} from './services/exportService';

type Screen='Home'|'Customers'|'Collections'|'Expenses'|'Reports'|'Team'|'Loans'|'Chits'|'Profile'|'Branding'|'Leaves';
type Session={role:Role;id:string;name:string;areaId?:string};
let appAreas:Area[]=seedAreas;
let appAgents:Agent[]=seedAgents;
const now=()=>{const d=new Date();return {date:d.toISOString().slice(0,10),time:d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}};

export default function App(){return <SafeAreaProvider><StatusBar style="dark"/><Root/></SafeAreaProvider>}
function Root(){const [session,setSession]=useState<Session|null>(null);const [customers,setCustomers]=useState(seedCustomers);const [collections,setCollections]=useState(seedCollections);const [expenses,setExpenses]=useState(seedExpenses);const [branding,setBranding]=useState<Branding>({companyName:'FINANCE360',logoUri:null});const [areas,setAreas]=useState(seedAreas);const [agents,setAgents]=useState(seedAgents);const [leaves,setLeaves]=useState(seedLeaves);appAreas=areas;appAgents=agents;if(!session)return <Login branding={branding} onLogin={setSession}/>;return <SafeAreaView style={{flex:1,backgroundColor:C.bg}} edges={['top','bottom']}><Shell session={session} branding={branding} setBranding={setBranding} customers={customers} collections={collections} expenses={expenses} areas={areas} agents={agents} leaves={leaves} setAreas={setAreas} setAgents={setAgents} setLeaves={setLeaves} setCustomers={setCustomers} setCollections={setCollections} setExpenses={setExpenses} logout={()=>setSession(null)}/></SafeAreaView>}
function Logo({branding,size=52}:{branding:Branding;size?:number}){return branding.logoUri?<Image source={{uri:branding.logoUri}} style={{width:size,height:size,borderRadius:size*.28}}/>:<View style={[s.logoFallback,{width:size,height:size,borderRadius:size*.28}]}><Text style={{color:C.white,fontSize:size*.42,fontWeight:'900'}}>₹</Text></View>}
function Login({onLogin,branding}:{onLogin:(s:Session)=>void;branding:Branding}){const [role,setRole]=useState<Role>('boy');const [user,setUser]=useState('B001');const [pass,setPass]=useState('123456');const [loading,setLoading]=useState(false);const change=(r:Role)=>{setRole(r);setUser(r==='boy'?'B001':r==='manager'?'M001':'C001')};const submit=()=>{setLoading(true);setTimeout(()=>{setLoading(false);if(pass!=='123456'){Alert.alert('Login failed','Demo password is 123456');return}if(role==='manager')onLogin({role,id:'M001',name:'Anil Kumar'});else if(role==='boy'){const a=appAgents.find(x=>x.id===user)||appAgents[0];onLogin({role,id:a.id,name:a.name,areaId:a.areaId})}else{const c=seedCustomers.find(x=>x.id===user)||seedCustomers[0];onLogin({role,id:c.id,name:c.name,areaId:c.areaId})}},350)};return <SafeAreaView style={ls.page}><Logo branding={branding} size={68}/><Text style={ls.brand}>{branding.companyName}</Text><Text style={ls.tag}>Secure collections • clear customer payments</Text><Card style={{width:'100%',maxWidth:440,marginTop:24}}><Text style={ls.title}>Welcome back</Text><Text style={ls.sub}>Choose your login</Text><View style={ls.roles}>{([['manager','Manager','Area control'],['boy','Collection Boy','Collections'],['customer','Customer','My account']] as const).map(([r,t,st])=><Pressable key={r} onPress={()=>change(r)} style={[ls.role,{borderColor:role===r?C.blue:C.border,backgroundColor:role===r?C.softBlue:'#fff'}]}><Text style={ls.roleIcon}>{r==='manager'?'◈':r==='boy'?'₹':'◉'}</Text><Text style={ls.roleTitle}>{t}</Text><Text style={ls.roleSub}>{st}</Text></Pressable>)}</View><Input label={role==='customer'?'Customer ID':role==='boy'?'Boy ID':'Manager ID'} value={user} onChangeText={setUser} placeholder="Enter ID"/><Input label="Password" value={pass} onChangeText={setPass} placeholder="Password"/><Button title={loading?'Signing in…':'Sign in'} onPress={submit} disabled={loading}/><Text style={ls.demo}>Demo password: 123456 • M001 • B001/B002 • C001</Text></Card></SafeAreaView>}

function Shell(p:{session:Session;branding:Branding;setBranding:React.Dispatch<React.SetStateAction<Branding>>;customers:Customer[];collections:Collection[];expenses:Expense[];areas:Area[];agents:Agent[];leaves:Leave[];setAreas:React.Dispatch<React.SetStateAction<Area[]>>;setAgents:React.Dispatch<React.SetStateAction<Agent[]>>;setLeaves:React.Dispatch<React.SetStateAction<Leave[]>>;setCustomers:React.Dispatch<React.SetStateAction<Customer[]>>;setCollections:React.Dispatch<React.SetStateAction<Collection[]>>;setExpenses:React.Dispatch<React.SetStateAction<Expense[]>>;logout:()=>void}){const {width}=useWindowDimensions();const tablet=width>=700;const [screen,setScreen]=useState<Screen>('Home');const [menu,setMenu]=useState(false);const {session}=p;const nav:Screen[]=session.role==='customer'?['Home','Collections','Profile']:['Home','Customers','Collections',...(session.role==='boy'?['Expenses' as Screen,'Leaves' as Screen]:['Reports' as Screen]),'Profile'];const title=session.role==='manager'?'Manager':session.role==='boy'?'Collection Boy':'Customer';return <View style={{flex:1}}><View style={s.header}><View style={{flexDirection:'row',alignItems:'center',gap:10}}><Logo branding={p.branding} size={40}/><View><Text style={s.eyebrow}>{p.branding.companyName} • {title.toUpperCase()}</Text><Text style={s.headerTitle}>{screen==='Home'?'Overview':screen}</Text></View></View><Pressable onPress={()=>setMenu(true)} style={s.avatar}><Text style={{fontWeight:'900',color:C.navy}}>{session.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</Text></Pressable></View><ScrollView contentContainerStyle={{paddingHorizontal:tablet?28:16,paddingBottom:100,maxWidth:1100,width:'100%',alignSelf:'center'}} showsVerticalScrollIndicator={false}>{screen==='Home'&&<Home {...p}/>}
{screen==='Customers'&&<CustomerList {...p}/>}
{screen==='Collections'&&<CollectionList {...p}/>}
{screen==='Expenses'&&<ExpenseList {...p}/>}
{screen==='Reports'&&<Reports {...p}/>}
{screen==='Team'&&<Team {...p}/>}
{screen==='Leaves'&&<LeaveManagement {...p}/>}
{screen==='Loans'&&<LoanView {...p}/>}
{screen==='Chits'&&<ChitView/>}
{screen==='Profile'&&<Profile {...p}/>}
{screen==='Branding'&&<BrandingSettings branding={p.branding} setBranding={p.setBranding}/>}</ScrollView><View style={s.bottom}>{nav.map(n=><Pressable key={n} onPress={()=>setScreen(n)} style={s.navItem}><Text style={[s.navIcon,screen===n&&{color:C.blue}]}>{n==='Home'?'⌂':n==='Customers'?'◉':n==='Collections'?'₹':n==='Expenses'?'▣':n==='Reports'?'▥':'☰'}</Text><Text style={[s.navText,screen===n&&{color:C.blue,fontWeight:'900'}]}>{n}</Text></Pressable>)}</View><Modal visible={menu} transparent animationType="slide" onRequestClose={()=>setMenu(false)}><Pressable style={s.modalBg} onPress={()=>setMenu(false)}><View style={s.drawer}><View style={{flexDirection:'row',alignItems:'center',gap:12,marginBottom:8}}><Logo branding={p.branding} size={52}/><View><Text style={s.drawerTitle}>{session.name}</Text><Text style={s.drawerSub}>{session.role==='manager'?'Area Manager':session.role==='boy'?`${appAreas.find(a=>a.id===session.areaId)?.name} Collection Team`:'Customer account'}</Text></View></View>{session.role==='manager'&&[['Team','Team'],['Leaves','Leaves'],['Reports','Reports'],['Loans','Loans'],['Chits','Chits'],['Branding','Branding']].map(([label,key])=><Pressable key={key} onPress={()=>{setMenu(false);setScreen(key as Screen)}} style={s.drawerItem}><Text style={s.drawerText}>{label}</Text><Text>›</Text></Pressable>)}{session.role==='boy'&&[['Customers','Customers'],['Expenses','Expenses'],['Leaves','Leaves']].map(([label,key])=><Pressable key={key} onPress={()=>{setMenu(false);setScreen(key as Screen)}} style={s.drawerItem}><Text style={s.drawerText}>{label}</Text><Text>›</Text></Pressable>)}<Button title="Close" secondary onPress={()=>setMenu(false)}/></View></Pressable></Modal></View>}

function Home(p:any){const {session,customers,collections,expenses,leaves=[]}=p;if(session.role==='customer')return <CustomerHome {...p}/>;const areaCustomers=session.role==='manager'?customers:customers.filter((c:Customer)=>c.areaId===session.areaId);const myCollections=session.role==='boy'?collections.filter((x:Collection)=>x.agentId===session.id):collections;const collected=myCollections.reduce((a:number,x:Collection)=>a+x.amount,0);const outstanding=areaCustomers.reduce((a:number,x:Customer)=>a+x.outstanding,0);const areaExpense=expenses.filter((e:Expense)=>session.role==='manager'||e.areaId===session.areaId).reduce((a:number,x:Expense)=>a+x.amount,0);return <><View style={s.hero}><View style={{flex:1}}><Text style={s.heroSmall}>{session.role==='manager'?'AREA OPERATIONS':'TODAY’S ROUTE'}</Text><Text style={s.heroTitle}>Hi, {session.name.split(' ')[0]} 👋</Text><Text style={s.heroSub}>{session.role==='manager'?'Monitor boys, collections and area finances.':`${appAreas.find(a=>a.id===session.areaId)?.name} • shared customer ledger`}</Text></View><Text style={s.heroIcon}>₹</Text></View><View style={s.metrics}>{[['Collected',money(collected),C.green],['Outstanding',money(outstanding),C.blue],['Expenses',money(areaExpense),C.amber]].map(([a,b,c])=><Card key={String(a)} style={s.metric}><View style={[s.metricIcon,{backgroundColor:c===C.green?C.softGreen:c===C.amber?C.softAmber:C.softBlue}]}><Text style={{color:c as string,fontSize:18,fontWeight:'900'}}>₹</Text></View><Text style={s.metricLabel}>{a}</Text><Text style={s.metricValue}>{b}</Text></Card>)}</View>{session.role==='manager'?<ManagerHome {...p}/>:<BoyHome {...p}/>}</>}
function ManagerHome({customers,collections}:any){return <><SectionTitle title="Area snapshot"/><View style={s.areaGrid}>{appAreas.map(a=><Card key={a.id} style={s.areaCard}><View style={s.rowBetween}><Text style={s.itemTitle}>{a.name}</Text><Status text={`${appAgents.filter(b=>b.areaId===a.id).length} boys`} type="neutral"/></View><Text style={s.muted}>{a.city}</Text><View style={s.miniLine}><Text>{customers.filter((c:Customer)=>c.areaId===a.id).length} customers</Text><Text>{money(collections.filter((x:Collection)=>x.areaId===a.id).reduce((n:number,x:Collection)=>n+x.amount,0))}</Text></View></Card>)}</View><SectionTitle title="Shared ledger"/><Card><Text style={s.bold}>One customer • one balance</Text><Text style={s.muted}>If one boy confirms a payment, every other assigned boy sees the same updated customer outstanding.</Text></Card></>}
function BoyHome({session,customers,collections}:any){const mine=customers.filter((c:Customer)=>c.areaId===session.areaId&&c.agentIds.includes(session.id));return <><SectionTitle title="My collection route" action={`${mine.length} customers`}/>{mine.slice(0,5).map((c:Customer)=><CustomerMini key={c.id} c={c} collections={collections}/>)}<Card style={s.reminderCard}><Text style={s.reminderTitle}>Leave reminders</Text><Text style={s.muted}>{session.role==='manager'?`${leaves.filter((x:Leave)=>x.status==='Pending').length} pending request(s) and ${leaves.filter((x:Leave)=>x.status==='Approved'&&x.fromDate>='2026-10-04').length} upcoming approved leave(s).`:''}</Text></Card></>}

function CustomerHome({session,customers,collections,branding}:any){const c=customers.find((x:Customer)=>x.id===session.id)!;const paidThisCycle=collections.filter((x:Collection)=>x.customerId===c.id).slice(0,1).reduce((n:number,x:Collection)=>n+x.amount,0);const remaining=Math.max(c.dueAmount-paidThisCycle,0);return <><View style={s.customerWelcome}><View style={{flex:1}}><Text style={s.heroSmall}>MY FINANCIAL ACCOUNT</Text><Text style={s.heroTitle}>Hello, {c.name.split(' ')[0]} 👋</Text><Text style={s.heroSub}>Your account is private. Only your payments and dues are shown.</Text></View><Logo branding={branding} size={54}/></View><Card style={s.balanceCard}><Text style={s.balanceLabel}>TOTAL OUTSTANDING</Text><Text style={s.balance}>{money(c.outstanding)}</Text><View style={s.dueRow}><View><Text style={s.balanceLabel}>THIS {c.frequency.toUpperCase()} DUE</Text><Text style={s.dueValue}>{money(c.dueAmount)}</Text></View><View><Text style={s.balanceLabel}>REMAINING TO PAY</Text><Text style={[s.dueValue,{color:remaining>0?C.amber:C.green}]}>{money(remaining)}</Text></View></View></Card><SectionTitle title="My profile"/><CustomerProfileCard c={c}/><SectionTitle title="Payment slips" action={`${collections.filter((x:Collection)=>x.customerId===c.id).length} receipts`}/>{collections.filter((x:Collection)=>x.customerId===c.id).map(x=><PaymentSlip key={x.id} item={x} customers={customers}/>)}</>}
function CustomerProfileCard({c}:{c:Customer}){return <Card><Info label="Customer ID" value={c.id}/><Info label="Full name" value={c.name}/><Info label="Mobile" value={c.phone}/><Info label="Email" value={c.email||'Not added'}/><Info label="Address" value={c.address||'Not added'}/><Info label="Area" value={appAreas.find(a=>a.id===c.areaId)?.name||'-'}/><Info label="Payment frequency" value={c.frequency}/><Info label="Assigned collection team" value={`${c.agentIds.length} boys`}/></Card>}
function Info({label,value}:{label:string;value:string}){return <View style={s.infoRow}><Text style={s.infoLabel}>{label}</Text><Text style={s.infoValue}>{value}</Text></View>}
function PaymentSlip({item,customers}:{item:Collection;customers:Customer[]}){const [show,setShow]=useState(false);const c=customers.find(x=>x.id===item.customerId);const a=appAgents.find(x=>x.id===item.agentId); const collectorName=a?.name|| (item.login==='M001'?'Anil Kumar':'Collection team');const download=async()=>{await exportPdf(`Payment Slip ${item.id}`,`<h2>Payment Confirmation</h2><p><b>Receipt:</b> ${item.id}</p><p><b>Customer:</b> ${c?.name||''}</p><p><b>Amount Paid:</b> ₹${item.amount}</p><p><b>Payment Method:</b> ${item.method}</p><p><b>Reference:</b> ${item.referenceNo||'Not applicable'}</p><p><b>Date:</b> ${item.date} ${item.time}</p><p><b>Collector:</b> ${collectorName} (${item.login})</p><p><b>Area:</b> ${appAreas.find(x=>x.id===item.areaId)?.name||''}</p><p><b>Principal:</b> ₹${item.principal} &nbsp; <b>Interest:</b> ₹${item.interest}</p><p><b>Proof:</b> ${item.proofKind||'Recorded'}</p><p><b>Status:</b> Confirmed by collector</p>`)};return <><Pressable onPress={()=>setShow(true)}><Card style={s.slip}><View style={s.slipTop}><View><Text style={s.itemTitle}>Receipt {item.id}</Text><Text style={s.muted}>{item.date} • {item.time}</Text></View><Status text="Confirmed" type="success"/></View><View style={s.slipAmount}><Text style={s.amount}>{money(item.amount)}</Text><Text style={s.muted}>{item.method} • {item.frequency}</Text></View><Text style={s.muted}>Collected by {collectorName} • Proof attached</Text><Text style={s.viewSlip}>View payment slip ›</Text></Card></Pressable><Modal visible={show} transparent animationType="fade" onRequestClose={()=>setShow(false)}><Pressable style={s.modalBg} onPress={()=>setShow(false)}><View style={s.slipModal} onStartShouldSetResponder={()=>true}><Text style={s.drawerTitle}>Payment confirmed</Text><Text style={s.muted}>Receipt {item.id}</Text><View style={s.receiptBox}><Info label="Customer" value={c?.name||''}/><Info label="Amount paid" value={money(item.amount)}/><Info label="Payment method" value={item.method}/><Info label="Reference / UTR" value={item.referenceNo||'Not applicable for cash'}/><Info label="Date & time" value={`${item.date} • ${item.time}`}/><Info label="Collector login" value={`${a?.name||''} • ${item.login}`}/><Info label="Area" value={appAreas.find(x=>x.id===item.areaId)?.name||''}/><Info label="Principal / Interest" value={`${money(item.principal)} / ${money(item.interest)}`}/><Info label="Proof" value={item.proofKind||'Recorded'}/><Info label="Verification" value={item.managerVerified?'Manager verified':'Collector confirmed'}/></View>{item.proofUri&&item.proofUri.startsWith('file')&&<Image source={{uri:item.proofUri}} style={s.receiptProof}/>}<Button title="Create PDF payslip" onPress={download}/><Button title="Close" secondary onPress={()=>setShow(false)}/></View></Pressable></Modal></>}

function CustomerMini({c,collections}:any){const last=collections.find((x:Collection)=>x.customerId===c.id);return <Card><View style={s.rowBetween}><View style={{flex:1}}><Text style={s.itemTitle}>{c.name}</Text><Text style={s.muted}>{c.phone} • shared with {c.agentIds.length} boys</Text></View><Status text={c.status} type={c.status==='Overdue'?'danger':c.status==='Closed'?'neutral':'success'}/></View><View style={s.miniLine}><Text>Outstanding</Text><Text style={s.bigAmount}>{money(c.outstanding)}</Text></View>{last&&<Text style={s.muted}>Last payment {money(last.amount)} • {last.date} • by {last.login}</Text>}</Card>}
function CustomerList(p:any){const {session,customers,collections}=p;const [q,setQ]=useState('');let list=customers;if(session.role==='boy')list=list.filter((c:Customer)=>c.areaId===session.areaId&&c.agentIds.includes(session.id));if(session.role==='customer')list=[];list=list.filter((c:Customer)=>c.name.toLowerCase().includes(q.toLowerCase())||c.phone.includes(q));return <><SectionTitle title={session.role==='boy'?'My Customers':'Customers'}/><Input label="Search" value={q} onChangeText={setQ} placeholder="Name or mobile number"/>{list.map((c:Customer)=><CustomerMini key={c.id} c={c} collections={collections}/>)}</>}
function CollectionList(p:any){const {session,collections,customers}=p;const [show,setShow]=useState(false);const list=(session.role==='boy'?collections.filter((x:Collection)=>x.agentId===session.id):session.role==='customer'?collections.filter((x:Collection)=>x.customerId===session.id&&x.status==='Confirmed'):collections).filter((x:Collection)=>x.status==='Confirmed');return <><SectionTitle title={session.role==='customer'?'My payment slips':'Collections'} action={session.role!=='customer'?'+ Record collection':undefined} onPress={()=>setShow(true)}/>{session.role==='customer'?<Text style={s.muted}>Only confirmed payments are issued as customer payment slips.</Text>:<Card><Text style={s.bold}>Proof-controlled shared ledger</Text><Text style={s.muted}>Every collection carries the collector, payment method and required proof. The customer balance is shared across all assigned boys.</Text></Card>}{list.map((x:Collection)=><PaymentSlip key={x.id} item={x} customers={customers}/>)}{show&&<CollectionModal {...p} close={()=>setShow(false)}/>}</>}
function CollectionModal({session,customers,setCustomers,setCollections,close,areaFilterId}:any){
  const allowed=customers.filter((c:Customer)=>areaFilterId?c.areaId===areaFilterId:(session.role==='manager'||(c.areaId===session.areaId&&c.agentIds.includes(session.id))));
  const [cid,setCid]=useState(allowed[0]?.id||'');
  const [amount,setAmount]=useState('');
  const [method,setMethod]=useState<'Cash'|'UPI'|'Bank'>('Cash');
  const [referenceNo,setReferenceNo]=useState('');
  const [proofUri,setProofUri]=useState<string|null>(null);
  const [busy,setBusy]=useState(false);
  const proofKind=method==='Cash'?'Customer confirmation photo':method==='UPI'?'UPI screenshot':'Bank transaction proof';
  const resetProof=()=>{setProofUri(null);setReferenceNo('')};
  const takePhoto=async()=>{
    const permission=await ImagePicker.requestCameraPermissionsAsync();
    if(!permission.granted){Alert.alert('Camera permission required','Allow camera access to capture the collection proof.');return}
    const result=await ImagePicker.launchCameraAsync({mediaTypes:['images'],allowsEditing:true,quality:.75});
    if(!result.canceled)setProofUri(result.assets[0].uri);
  };
  const choosePhoto=async()=>{
    const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();
    if(!permission.granted){Alert.alert('Photo permission required','Allow photo access to select the collection proof.');return}
    const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:true,quality:.75});
    if(!result.canceled)setProofUri(result.assets[0].uri);
  };
  const save=()=>{
    const n=Number(amount);const c=customers.find((x:Customer)=>x.id===cid);
    if(!c||!n||n<=0){Alert.alert('Check amount','Enter a valid collection amount.');return}
    if(n>c.outstanding){Alert.alert('Amount too high','Collection cannot exceed current outstanding.');return}
    if(!proofUri){Alert.alert('Proof required',`${proofKind} is required before this collection can be confirmed.`);return}
    if((method==='UPI'||method==='Bank')&&!referenceNo.trim()){Alert.alert('Reference required',`${method==='UPI'?'UTR':'Bank reference / UTR'} is required.`);return}
    setBusy(true);
    const t=now();const receipt=`FIN-${Date.now().toString().slice(-7)}`;
    const item:Collection={id:receipt,customerId:c.id,agentId:session.role==='boy'?session.id:'M001',areaId:c.areaId,amount:n,principal:Math.max(0,n-Math.round(n*.1)),interest:Math.min(n,Math.round(n*.1)),date:t.date,time:t.time,method,type:'Loan',login:session.id,frequency:c.frequency,status:'Confirmed',proofUri,proofKind,referenceNo:referenceNo.trim()||undefined,collectorConfirmedAt:new Date().toISOString(),managerVerified:session.role==='manager'};
    setCollections((old:Collection[])=>[item,...old]);
    setCustomers((old:Customer[])=>old.map(x=>x.id===c.id?{...x,outstanding:x.outstanding-n}:x));
    setBusy(false);close();Alert.alert('Payment confirmed',`Receipt ${receipt} created. The customer can now see the payment slip.`)
  };
  return <Modal visible transparent animationType="slide" onRequestClose={close}><Pressable style={s.modalBg} onPress={close}><View style={s.formSheet} onStartShouldSetResponder={()=>true}>
    <Text style={s.drawerTitle}>Confirm collection</Text><Text style={s.drawerSub}>Required proof is stored against the same financial transaction.</Text>
    <ScrollView keyboardShouldPersistTaps="handled">
      {allowed.slice(0,8).map((c:Customer)=><Pressable key={c.id} onPress={()=>{setCid(c.id);resetProof()}} style={[s.customerPick,c.id===cid&&{borderColor:C.blue,backgroundColor:C.softBlue}]}><View style={{flex:1}}><Text style={s.bold}>{c.name}</Text><Text style={s.muted}>Outstanding {money(c.outstanding)} • Due {money(c.dueAmount)}</Text></View><Text style={{color:c.id===cid?C.blue:C.muted,fontWeight:'900'}}>✓</Text></Pressable>)}
      <Input label="Amount collected" value={amount} onChangeText={setAmount} placeholder="₹ 0" keyboardType="numeric"/>
      <Text style={s.label}>Payment method</Text><View style={s.methodRow}>{(['Cash','UPI','Bank'] as const).map(x=><Pill key={x} text={x} active={method===x} onPress={()=>{setMethod(x);setReferenceNo('');setProofUri(null)}}/>)}</View>
      {method!=='Cash'&&<Input label={method==='UPI'?'UTR / UPI transaction ID':'Bank reference / UTR'} value={referenceNo} onChangeText={setReferenceNo} placeholder={method==='UPI'?'e.g. 123456789012':'e.g. UTR987654321'} autoCapitalize="characters"/>}
      <Card style={s.proofCard}><Text style={s.bold}>{proofKind}</Text><Text style={s.muted}>{method==='Cash'?'Capture the customer confirmation/signature photo.':method==='UPI'?'Capture or select the successful UPI payment screenshot.':'Capture or select the bank transfer confirmation/proof.'}</Text>{proofUri?<View style={{marginTop:12}}><Image source={{uri:proofUri}} style={s.proofPreview}/><View style={{flexDirection:'row',gap:8,marginTop:8}}><Button title="Retake / replace" secondary onPress={takePhoto}/><Button title="Remove" secondary onPress={()=>setProofUri(null)}/></View></View>:<View style={{flexDirection:'row',gap:8,marginTop:12}}><Button title="Take photo" onPress={takePhoto}/><Button title="Choose photo" secondary onPress={choosePhoto}/></View>}</Card>
      <View style={s.proofRule}><Text style={s.proofRuleTitle}>Before confirmation</Text><Text style={s.muted}>{method==='Cash'?'Cash requires customer confirmation photo.':method==='UPI'?'UPI requires both UTR and payment screenshot.':'Bank requires both reference/UTR and transaction proof.'}</Text></View>
      <Button title={busy?'Saving…':'Confirm & issue receipt'} onPress={save} disabled={busy}/>
    </ScrollView>
  </View></Pressable></Modal>
}
function ExpenseList({session,expenses}:any){
  const rows:Expense[]=session.role==='boy'?expenses.filter((e:Expense)=>e.agentId===session.id):expenses;
  const total=rows.reduce((sum:number,e:Expense)=>sum+e.amount,0);
  return <><SectionTitle title="Company expenses" action={money(total)}/><Card><Text style={s.bold}>Company-paid field expenses</Text><Text style={s.muted}>Food, petrol, travel and other approved expenses are tracked separately from customer collections.</Text></Card>{rows.map((e:Expense)=><Card key={e.id}><View style={s.rowBetween}><View style={{flex:1}}><Text style={s.itemTitle}>{e.type}</Text><Text style={s.muted}>{e.date} • {appAreas.find(a=>a.id===e.areaId)?.name||'Area'} • {e.agentId}</Text></View><Text style={s.amount}>{money(e.amount)}</Text></View><Text style={[s.muted,{marginTop:8}]}>{e.note}</Text></Card>)}</>
}
function ExpenseModal({session,setExpenses,close}:any){const [type,setType]=useState<'Food'|'Petrol'|'Travel'|'Other'>('Petrol');const [amount,setAmount]=useState('');const [note,setNote]=useState('');const save=()=>{const n=Number(amount);if(!n)return;const t=now();setExpenses((old:Expense[])=>[{id:`EXP-${Date.now()}`,areaId:session.areaId,agentId:session.id,type,amount:n,date:t.date,note:note||'Field expense'},...old]);close()};return <Modal visible transparent animationType="slide"><Pressable style={s.modalBg} onPress={close}><View style={s.formSheet} onStartShouldSetResponder={()=>true}><Text style={s.drawerTitle}>Add company expense</Text><View style={s.methodRow}>{(['Petrol','Food','Travel','Other'] as const).map(x=><Pill key={x} text={x} active={type===x} onPress={()=>setType(x)}/>)}</View><Input label="Amount" value={amount} onChangeText={setAmount} placeholder="₹ 0" keyboardType="numeric"/><Input label="Note" value={note} onChangeText={setNote} placeholder="e.g. train ticket"/><Button title="Save expense" onPress={save}/></View></Pressable></Modal>}
function Reports(p:any){const {session,customers,collections,expenses,branding}=p;const rows=session.role==='boy'?collections.filter((x:Collection)=>x.agentId===session.id):collections;const total=rows.reduce((a:number,x:Collection)=>a+x.amount,0);const generated=new Date().toLocaleString();const exportRows=rows.map((x:Collection)=>{const c=customers.find((z:Customer)=>z.id===x.customerId);const a=appAgents.find(z=>z.id===x.agentId);return {'Receipt ID':x.id,'Customer Name':c?.name||'','Date':x.date,'Time':x.time,'Amount':x.amount,'Area':appAreas.find(z=>z.id===x.areaId)?.name||'','Area Name':appAreas.find(z=>z.id===x.areaId)?.name||'','Collector Name':a?.name|| (x.login==='M001'?'Anil Kumar':''),'Login':x.login,'Payment Method':x.method,'Reference / UTR':x.referenceNo||'','Status':x.status}});const pdfHtml=`<div style="font-family:Arial;padding:24px"><div style="border-bottom:2px solid #163A63;padding-bottom:12px"><div style="font-size:24px;font-weight:bold;color:#163A63">◉ ${branding.companyName}</div><div style="font-size:18px;font-weight:bold;margin-top:8px">Financial Collection Report</div><div style="font-size:11px;color:#666;margin-top:4px">Generated: ${generated}</div></div><div style="margin:16px 0;padding:12px;background:#F1F6FF"><b>Total confirmed collections:</b> ₹${total.toLocaleString('en-IN')}</div><table style="width:100%;border-collapse:collapse;font-size:9px"><thead><tr>${['Receipt ID','Customer','Date','Time','Amount','Area','Collector / Login','Method','Reference / UTR','Status'].map(h=>`<th style="border:1px solid #CCC;padding:6px;background:#163A63;color:white;text-align:left">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>{const c=customers.find((z:Customer)=>z.id===x.customerId);const a=appAgents.find(z=>z.id===x.agentId);return `<tr>${[x.id,c?.name||'',x.date,x.time,`₹${x.amount.toLocaleString('en-IN')}`,appAreas.find(z=>z.id===x.areaId)?.name||'',`${a?.name||''} / ${x.login}`,x.method,x.referenceNo||'—',x.status].map(v=>`<td style="border:1px solid #DDD;padding:5px">${v}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`;return <><SectionTitle title="Reports"/><Card style={s.reportHero}><Text style={s.heroSmall}>CONFIRMED COLLECTIONS</Text><Text style={s.reportTotal}>{money(total)}</Text><Text style={{color:'#DCE7FF'}}>Generated {generated}</Text></Card><View style={s.exportGrid}><Pressable style={s.exportCard} onPress={()=>exportExcel(exportRows,'financial-collection-report.xlsx',branding.companyName,'Financial Collection Report')}><Text style={s.exportIcon}>▤</Text><Text style={s.bold}>Excel</Text><Text style={s.muted}>Branded header + generated date + detailed columns</Text></Pressable><Pressable style={s.exportCard} onPress={()=>exportPdf('Financial Collection Report',pdfHtml)}><Text style={s.exportIcon}>▥</Text><Text style={s.bold}>PDF</Text><Text style={s.muted}>Branded header + logo/name + generated date</Text></Pressable></View><SectionTitle title="Report columns"/><Card>{['Receipt ID','Customer Name','Date & Time','Amount','Area / Area Name','Collector Name / Login','Payment Method','Reference / UTR','Status'].map(x=><View key={x} style={s.check}><Text style={{color:C.green,fontWeight:'900'}}>✓</Text><Text style={s.bold}>{x}</Text></View>)}</Card><Text style={s.muted}>Company expenses: {money(expenses.reduce((a:number,e:Expense)=>a+e.amount,0))}</Text></>}
function Team(p:any){return <ManagerTeam {...p}/>}
function ManagerTeam(p:any){const {areas,agents,setAreas,setAgents}=p;const [areaModal,setAreaModal]=useState(false);const [boyModal,setBoyModal]=useState(false);const [assignModal,setAssignModal]=useState(false);const [collectArea,setCollectArea]=useState<string|null>(null);const [name,setName]=useState('');const [city,setCity]=useState('Hyderabad');const [phone,setPhone]=useState('');const [boyArea,setBoyArea]=useState('UNASSIGNED');const [selectedBoy,setSelectedBoy]=useState('');const [selectedArea,setSelectedArea]=useState('');const addArea=()=>{if(!name.trim()){Alert.alert('Area name required');return}const id=`A${String(areas.length+1).padStart(2,'0')}`;setAreas([...areas,{id,name:name.trim(),city:city.trim()||'Hyderabad',boys:0,customers:0}]);setName('');setCity('Hyderabad');setAreaModal(false);Alert.alert('Area created','The area is ready for boy assignment.')};const addBoy=()=>{if(!name.trim()||phone.trim().length<10){Alert.alert('Enter boy name and valid mobile number');return}const id=`B${String(agents.length+1).padStart(3,'0')}`;setAgents([...agents,{id,name:name.trim(),phone:phone.trim(),areaId:'UNASSIGNED',active:false}]);setName('');setPhone('');setBoyModal(false);Alert.alert('Boy profile created',`Login ID: ${id}`)};const assign=()=>{if(!selectedBoy||!selectedArea){Alert.alert('Select boy and area');return}const target=agents.find((b:Agent)=>b.id===selectedBoy);if(target?.areaId&&target.areaId!=='UNASSIGNED'){Alert.alert('Unassign first','This boy is already assigned to an area. Unassign the boy first, then assign a new area.');return}setAgents(agents.map((b:Agent)=>b.id===selectedBoy?{...b,areaId:selectedArea,active:true}:b));setAssignModal(false);setSelectedBoy('');setSelectedArea('')};const unassign=(id:string)=>setAgents(agents.map((b:Agent)=>b.id===id?{...b,areaId:'UNASSIGNED',active:false}:b));return <><SectionTitle title="Area & boy management"/><Card style={s.ruleCard}><Text style={s.ruleTitle}>Assignment rule</Text><Text style={s.muted}>A boy can belong to only one area at a time. To move a boy, first unassign them, then assign them to the new area.</Text></Card><View style={{flexDirection:'row',gap:8,marginBottom:10}}><View style={{flex:1}}><Button title="+ Create area" onPress={()=>{setName('');setAreaModal(true)}}/></View><View style={{flex:1}}><Button title="+ Create boy" secondary onPress={()=>{setName('');setPhone('');setBoyArea('UNASSIGNED');setBoyModal(true)}}/></View></View><Button title="Assign unassigned boy" secondary onPress={()=>setAssignModal(true)}/><SectionTitle title="Areas"/>{areas.map((a:Area)=><Card key={a.id}><View style={s.rowBetween}><View><Text style={s.itemTitle}>{a.name}</Text><Text style={s.muted}>{a.city} • {agents.filter((b:Agent)=>b.areaId===a.id).length} boys</Text></View><Status text="Manager access" type="neutral"/></View>{agents.filter((b:Agent)=>b.areaId===a.id).map((b:Agent)=><View key={b.id} style={s.teamRow}><View style={s.avatarSmall}><Text style={s.bold}>{b.name[0]}</Text></View><View style={{flex:1}}><Text style={s.bold}>{b.name}</Text><Text style={s.muted}>{b.phone} • {b.id}</Text></View><Pressable onPress={()=>unassign(b.id)}><Text style={{color:C.red,fontWeight:'900'}}>Unassign</Text></Pressable></View>)}<Button title="Enter area & collect money" onPress={()=>setCollectArea(a.id)}/></Card>)}<Card><Text style={s.bold}>Unassigned boys</Text>{agents.filter((b:Agent)=>b.areaId==='UNASSIGNED').map((b:Agent)=><View key={b.id} style={s.teamRow}><View style={s.avatarSmall}><Text style={s.bold}>{b.name[0]}</Text></View><View style={{flex:1}}><Text style={s.bold}>{b.name}</Text><Text style={s.muted}>{b.phone} • {b.id}</Text></View><Status text="Unassigned" type="warning"/></View>)}</Card>{areaModal&&<SimpleModal title="Create area" close={()=>setAreaModal(false)}><Input label="Area name" value={name} onChangeText={setName} placeholder="e.g. Kondapur"/><Input label="City" value={city} onChangeText={setCity} placeholder="Hyderabad"/><Button title="Create area" onPress={addArea}/></SimpleModal>}{boyModal&&<SimpleModal title="Create boy profile" close={()=>setBoyModal(false)}><Input label="Boy full name" value={name} onChangeText={setName} placeholder="Full name"/><Input label="Mobile number" value={phone} onChangeText={setPhone} placeholder="10 digit mobile" keyboardType="phone-pad"/><View style={s.ruleCard}><Text style={s.ruleTitle}>New boy starts unassigned</Text><Text style={s.muted}>Create the profile first. Then use “Assign unassigned boy” to place the boy in exactly one area.</Text></View><Button title="Create boy" onPress={addBoy}/></SimpleModal>}{assignModal&&<SimpleModal title="Assign unassigned boy" close={()=>setAssignModal(false)}><Text style={s.label}>Boy</Text><View style={s.methodRow}>{agents.filter((b:Agent)=>b.areaId==='UNASSIGNED').map((b:Agent)=><Pill key={b.id} text={b.name} active={selectedBoy===b.id} onPress={()=>setSelectedBoy(b.id)}/>)}</View><Text style={s.label}>Area</Text><View style={s.methodRow}>{areas.map((a:Area)=><Pill key={a.id} text={a.name} active={selectedArea===a.id} onPress={()=>setSelectedArea(a.id)}/>)}</View><Button title="Assign boy" onPress={assign}/></SimpleModal>}{collectArea&&<CollectionModal {...p} areaFilterId={collectArea} close={()=>setCollectArea(null)}/>}</>}
function SimpleModal({title,close,children}:{title:string;close:()=>void;children:React.ReactNode}){return <Modal visible transparent animationType="slide" onRequestClose={close}><Pressable style={s.modalBg} onPress={close}><View style={s.formSheet} onStartShouldSetResponder={()=>true}><Text style={s.drawerTitle}>{title}</Text><ScrollView keyboardShouldPersistTaps="handled">{children}</ScrollView><View style={{marginTop:10}}><Button title="Cancel" secondary onPress={close}/></View></View></Pressable></Modal>}
function LeaveManagement(p:any){const {session,agents,leaves,setLeaves}=p;if(session.role==='boy')return <BoyLeaveApply {...p}/>;const update=(id:string,status:Leave['status'])=>setLeaves(leaves.map((x:Leave)=>x.id===id?{...x,status}:x));const pending=leaves.filter((x:Leave)=>x.status==='Pending');const upcoming=leaves.filter((x:Leave)=>x.status==='Approved'&&x.toDate>='2026-10-04');return <><SectionTitle title="Leave management" action={`${pending.length} pending`}/><Card style={s.reminderCard}><Text style={s.reminderTitle}>Manager reminders</Text><Text style={s.muted}>{upcoming.length?`${upcoming.length} approved leave(s) are upcoming. Review the dates before planning area collections.`:'No upcoming approved leaves.'}</Text>{upcoming.slice(0,5).map((x:Leave)=><View key={x.id} style={s.reminderRow}><Text style={s.bold}>{agents.find((b:Agent)=>b.id===x.agentId)?.name||x.agentId}</Text><Text style={s.muted}>{x.fromDate} → {x.toDate}</Text></View>)}</Card><Text style={s.sectionLabel}>Requests requiring approval</Text>{pending.map((x:Leave)=><Card key={x.id}><View style={s.rowBetween}><View style={{flex:1}}><Text style={s.itemTitle}>{agents.find((b:Agent)=>b.id===x.agentId)?.name||x.agentId}</Text><Text style={s.muted}>{x.fromDate} → {x.toDate}</Text><Text style={s.muted}>{x.reason}</Text><Text style={s.muted}>Applied {x.createdAt||'Recently'}</Text></View><Status text="Pending" type="warning"/></View><View style={{flexDirection:'row',gap:8,marginTop:12}}><View style={{flex:1}}><Button title="Approve" onPress={()=>update(x.id,'Approved')}/></View><View style={{flex:1}}><Button title="Reject" secondary onPress={()=>update(x.id,'Rejected')}/></View></View></Card>)}<Text style={s.sectionLabel}>Leave history</Text>{leaves.map((x:Leave)=><Card key={x.id}><View style={s.rowBetween}><View style={{flex:1}}><Text style={s.itemTitle}>{agents.find((b:Agent)=>b.id===x.agentId)?.name||x.agentId}</Text><Text style={s.muted}>{x.fromDate} → {x.toDate} • {x.reason}</Text></View><Status text={x.status} type={x.status==='Approved'?'success':x.status==='Rejected'?'danger':'warning'}/></View></Card>)}</>}
function formatPickerDate(date:Date){const y=date.getFullYear();const m=String(date.getMonth()+1).padStart(2,'0');const d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`}
function BoyLeaveApply(p:any){const {session,leaves,setLeaves}=p;const today=new Date();today.setHours(0,0,0,0);const initialFrom=new Date(today);initialFrom.setDate(initialFrom.getDate()+1);const initialTo=new Date(initialFrom);const [fromDate,setFromDate]=useState(initialFrom);const [toDate,setToDate]=useState(initialTo);const [picker,setPicker]=useState<'from'|'to'|null>(null);const [reason,setReason]=useState('');const apply=()=>{const from=formatPickerDate(fromDate),to=formatPickerDate(toDate);if(!reason.trim()){Alert.alert('Reason required','Please enter a reason for the leave.');return}if(fromDate<today){Alert.alert('Invalid date','Leave must be applied for a future date.');return}if(toDate<fromDate){Alert.alert('Invalid date','To date cannot be before From date.');return}const item:Leave={id:`LV${String(leaves.length+1).padStart(3,'0')}`,agentId:session.id,fromDate:from,toDate:to,reason:reason.trim(),status:'Pending',createdBy:session.id,createdAt:new Date().toLocaleDateString()};setLeaves([item,...leaves]);setReason('');Alert.alert('Leave submitted','Your manager will review this request.');};return <><SectionTitle title="My leave"/><Card style={s.leaveHero}><Text style={s.heroSmall}>LEAVE REQUEST</Text><Text style={s.heroTitle}>Plan your leave early</Text><Text style={s.heroSub}>You can apply up to two months in advance. Manager approval is required before leave becomes active.</Text></Card><Card><Text style={s.label}>From date</Text><Pressable style={s.dateButton} onPress={()=>setPicker('from')}><Text style={s.dateButtonText}>{formatPickerDate(fromDate)}</Text><Text style={s.dateIcon}>▣</Text></Pressable><Text style={s.label}>To date</Text><Pressable style={s.dateButton} onPress={()=>setPicker('to')}><Text style={s.dateButtonText}>{formatPickerDate(toDate)}</Text><Text style={s.dateIcon}>▣</Text></Pressable><Input label="Reason" value={reason} onChangeText={setReason} placeholder="Family / personal / medical"/><Button title="Apply for leave" onPress={apply}/></Card><SectionTitle title="My requests"/>{leaves.filter((x:Leave)=>x.agentId===session.id).map((x:Leave)=><Card key={x.id}><View style={s.rowBetween}><View><Text style={s.itemTitle}>{x.fromDate} → {x.toDate}</Text><Text style={s.muted}>{x.reason}</Text></View><Status text={x.status} type={x.status==='Approved'?'success':x.status==='Rejected'?'danger':'warning'}/></View></Card>)}{picker&&<Modal visible transparent animationType="fade" onRequestClose={()=>setPicker(null)}><Pressable style={s.modalBg} onPress={()=>setPicker(null)}><View style={s.datePickerSheet} onStartShouldSetResponder={()=>true}><Text style={s.drawerTitle}>{picker==='from'?'Select start date':'Select end date'}</Text><Text style={s.muted}>Choose the leave date from the calendar.</Text><DateTimePicker value={picker==='from'?fromDate:toDate} onValueChange={(_,selectedDate)=>{if(selectedDate){if(picker==='from')setFromDate(selectedDate);else setToDate(selectedDate)}}} mode="date" display="calendar" minimumDate={today}/><Button title="Done" onPress={()=>setPicker(null)}/></View></Pressable></Modal>}</>}
function LoanView({customers}:any){return <><SectionTitle title="Loans"/>{loans.map(l=><Card key={l.id}><View style={s.rowBetween}><View><Text style={s.itemTitle}>{customers.find((c:Customer)=>c.id===l.customerId)?.name}</Text><Text style={s.muted}>{l.id} • {l.frequency} • {l.interestRate}%</Text></View><Status text={l.status} type="success"/></View><View style={s.miniLine}><Text>Principal {money(l.principal)}</Text><Text>Outstanding {money(l.outstanding)}</Text></View></Card>)}</>}
function ChitView(){return <><SectionTitle title="Weekly & Monthly Chits"/>{chits.map(c=><Card key={c.id}><View style={s.rowBetween}><View><Text style={s.itemTitle}>{c.name}</Text><Text style={s.muted}>{c.frequency} • {c.members} members</Text></View><Status text={c.status} type={c.status==='Running'?'success':'neutral'}/></View><View style={s.miniLine}><Text>Installment {money(c.installment)}</Text><Text>Pending {money(c.pending)}</Text></View></Card>)}</>}
function Profile(p:any){const {session,logout,branding,setBranding}=p;return <><Card><View style={{alignItems:'center',paddingVertical:8}}><Logo branding={branding} size={76}/><Text style={[s.itemTitle,{fontSize:20,marginTop:10}]}>{session.name}</Text><Text style={s.muted}>{session.role.toUpperCase()} • {session.id}</Text>{session.areaId&&<Text style={s.muted}>{appAreas.find(a=>a.id===session.areaId)?.name}</Text>}</View></Card>{session.role==='manager'&&<><SectionTitle title="Company branding"/><BrandingSettings branding={branding} setBranding={setBranding}/></>}<Button title="Logout" secondary onPress={logout}/></>}
function BrandingSettings({branding,setBranding}:{branding:Branding;setBranding:React.Dispatch<React.SetStateAction<Branding>>}){const [name,setName]=useState(branding.companyName);const pick=async()=>{const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted){Alert.alert('Permission required','Please allow photo access to select a company logo.');return}const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],allowsEditing:true,aspect:[1,1],quality:.8});if(!result.canceled)setBranding(b=>({...b,logoUri:result.assets[0].uri}))};const save=()=>{const clean=name.trim();if(!clean){Alert.alert('Company name required');return}setBranding(b=>({...b,companyName:clean}));Alert.alert('Branding updated','The new company name and logo are now shown across the mobile app.');};return <Card><View style={{alignItems:'center'}}><Logo branding={branding} size={92}/><Button title="Choose company logo" secondary onPress={pick}/></View><Input label="Company name" value={name} onChangeText={setName} placeholder="Enter company name"/><Text style={s.muted}>The manager can change the branding used by Manager, Boy and Customer mobile screens. In production, the logo/name should be stored centrally in the backend so every device receives the same branding.</Text><Button title="Save branding" onPress={save}/></Card>}

